import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, positionLocal, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  // Root container
  const container = new Group();

  // Design Tokens
  const colors = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradStart: '#1a1a22',
    gradEnd: '#121218'
  };

  // Backstage Gradient Plane (STAGES TO VOID DEFECT prevention)
  const backdropGeo = new PlaneGeometry(10, 8);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1
  });

  // Vertical gradient shader using TSL
  const gradientNode = mix(
    vec3(0.06, 0.06, 0.08), // dark base
    vec3(0.1, 0.1, 0.13),   // slightly lighter top
    uv().y
  );
  backdropMat.colorNode = gradientNode;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // Local Lighting Setup
  // Key light rakes at 35deg elevation so brushed anisotropic highlight sweeps across units
  const localKeyLight = new DirectionalLight(0xffffff, 1.4);
  localKeyLight.position.set(2, 1.4, 3); // 35-degree elevation / side angle rake
  container.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.5);
  localRimLight.position.set(-3, -2, -1);
  container.add(localRimLight);

  const localAmbient = new AmbientLight(0xffffff, 0.4);
  container.add(localAmbient);

  // Core Layout Group
  const gridGroup = new Group();
  container.add(gridGroup);

  // 1. Kicker Setup ("AS FEATURED IN")
  const kickerItem = (config.textContent ?? []).find(item => item.role === 'kicker') || { text: 'AS FEATURED IN' };
  const kickerText = ctx.fontAtlas.createText(kickerItem.text, {
    fontSize: 14, // scaled for scene metrics
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 3
  });
  // Position kicker above grid (grid total ~1.49h centered, top is at ~0.75, so kicker is at ~1.15)
  kickerText.position.set(0, 1.15, 0.05);
  gridGroup.add(kickerText);

  // 2. 3x2 Grid Coordinates and Specifications
  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const columns = 3;
  const rows = 2;

  // Calculate starts so grid is perfectly centered
  const totalWidth = columns * tileWidth + (columns - 1) * gap;
  const totalHeight = rows * tileHeight + (rows - 1) * gap;
  const startX = -totalWidth / 2 + tileWidth / 2;
  const startY = totalHeight / 2 - tileHeight / 2;

  // Filter out the kicker to loop through brand marks
  const brandMarks = (config.textContent ?? []).filter(item => item.role !== 'kicker');
  const fallbackBrands = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];

  const timelines = [];
  const tilesInteractive = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < columns; c++) {
      const idx = r * columns + c;
      const brandTextStr = (brandMarks[idx] ? brandMarks[idx].text : fallbackBrands[idx]) || 'BRAND';

      // Create Individual Tile Container (helps with nested scale and translation)
      const tileContainer = new Group();
      tileContainer.position.set(
        startX + c * (tileWidth + gap),
        startY - r * (tileHeight + gap),
        0
      );
      gridGroup.add(tileContainer);

      // Chamfered / Brushed PBR Tile Mesh
      const tileGeo = new PlaneGeometry(tileWidth, tileHeight, 4, 4);
      const tileMat = new MeshStandardNodeMaterial({
        roughness: 0.55,
        metalness: 0.5,
        clearcoat: 0.2,
        clearcoatRoughness: 0.3
      });

      // Machined metal PBR vertical ramp color mapping using TSL
      const tileGrad = mix(
        vec3(0.07, 0.07, 0.09), // #121218 bottom
        vec3(0.1, 0.1, 0.13),   // #1a1a22 top
        uv().y
      );
      tileMat.colorNode = tileGrad;

      const tileMesh = new Mesh(tileGeo, tileMat);
      tileContainer.add(tileMesh);

      // Create Brand-Mark Text
      const textNode = ctx.fontAtlas.createText(brandTextStr, {
        fontSize: 16,
        color: colors.paper,
        align: 'center'
      });
      // Flatten & lower opacity per visual spec (78% opacity baseline)
      textNode.position.set(0, 0, 0.02);
      textNode.scale.setScalar(0.8);

      // We target opacity of the text meshes inside textNode
      textNode.traverse((child) => {
        if (child.material) {
          child.material.transparent = true;
          child.material.opacity = 0.78;
        }
      });
      tileContainer.add(textNode);

      // Initial Mount state for staggered animation
      tileContainer.position.y -= 0.2;
      tileContainer.scale.set(0.001, 0.001, 1);

      // Animate Entrance
      const delay = (r * columns + c) * 0.08;
      gsap.to(tileContainer.scale, {
        x: 1,
        y: 1,
        duration: 0.5,
        delay: delay,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      });

      gsap.to(tileContainer.position, {
        y: startY - r * (tileHeight + gap),
        z: 0,
        duration: 0.6,
        delay: delay,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      });

      // Hover / Interaction logic bound to individual user interactions
      tilesInteractive.push({
        box: tileMesh,
        container: tileContainer,
        text: textNode,
        initialZ: 0,
        initialY: startY - r * (tileHeight + gap)
      });
    }
  }

  // Handle Event Triggers (Pointer Hover) using custom handlers
  const raycaster = new ctx.THREE.Raycaster();
  const pointer = new ctx.THREE.Vector2();

  let activeHoveredTile = null;

  const handlePointerMove = (event) => {
    // Adapter provides standardized client coordinates or pre-normalized values
    if (!event.pointer) return;
    pointer.copy(event.pointer);

    // We expect the global system to handle raycasting or pass direct userData handlers.
  };

  // Modern Node API Custom Handlers mapped directly to local structures
  container.userData.handlers = {
    onPointerOver: (event) => {
      // Find matches manually via target detection if needed, or trigger hover response per individual mesh
      const targetMesh = event.intersection?.object;
      if (!targetMesh) return;

      const matched = tilesInteractive.find(t => t.box === targetMesh);
      if (matched && activeHoveredTile !== matched) {
        activeHoveredTile = matched;

        // Translate Z and upscale opacity
        gsap.to(matched.container.position, {
          z: 0.08,
          duration: 0.16,
          ease: 'power2.out'
        });

        matched.text.traverse((child) => {
          if (child.material) {
            gsap.to(child.material, { opacity: 1.0, duration: 0.16 });
          }
        });
      }
    },
    onPointerOut: () => {
      if (activeHoveredTile) {
        gsap.to(activeHoveredTile.container.position, {
          z: 0,
          duration: 0.25,
          ease: 'power2.inOut'
        });

        activeHoveredTile.text.traverse((child) => {
          if (child.material) {
            gsap.to(child.material, { opacity: 0.78, duration: 0.25 });
          }
        });
        activeHoveredTile = null;
      }
    }
  };

  // Safe resource disposal & timeline killing
  container.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    tilesInteractive.forEach(tile => {
      tile.box.geometry.dispose();
      tile.box.material.dispose();
    });
  };

  return container;
}
